import os
import json
import time
from typing import List, Dict, Any, Generator

from fastapi import FastAPI, Request, HTTPException
from fastapi.responses import StreamingResponse, JSONResponse, FileResponse
from fastapi.middleware.cors import CORSMiddleware
import requests

 Exa SDK import (docs show a python sdk; package name used here is exa_py)
try:
    from exa import Exa   adjust if actual SDK exposes different import path
    HAS_EXA_SDK = True
except Exception:
    HAS_EXA_SDK = False

 Cerebras SDK optional
try:
    from cerebras.cloud.sdk import Cerebras
    HAS_CEREBRAS = True
except Exception:
    HAS_CEREBRAS = False

app = FastAPI()
app.add_middleware(CORSMiddleware, allow_origins=[""], allow_methods=[""], allow_headers=[""])

 Secrets from Replit secrets
CEREBRAS_KEY = os.getenv("CEREBRAS_API_KEY", "")
CEREBRAS_URL = os.getenv("CEREBRAS_API_URL", "")
OPENAI_KEY = os.getenv("OPENAI_API_KEY", "")
EXA_KEY = os.getenv("EXA_API_KEY", "")

 Models defaults
CEREBRAS_MODEL = os.getenv("CEREBRAS_MODEL", "gptoss120b")
OPENAI_MODEL = os.getenv("OPENAI_MODEL", "gpt5")
EXA_MODEL_CHAT = "exa"
EXA_MODEL_RESEARCH = "exaresearch"
CEREBRAS_MAX_TOKENS = int(os.getenv("CEREBRAS_MAX_TOKENS", "65536"))

ROOT = os.path.dirname(__file__) or "."

 Serve frontend
@app.get("/")
def index():
    return FileResponse(os.path.join(ROOT, "index.html"))

@app.get("/manifest.json")
def manifest():
    m = {
        "name": "Jade Chat",
        "short_name": "Jade",
        "start_url": "/",
        "display": "standalone",
        "background_color": "071014",
        "theme_color": "071014",
        "icons": [
            {"src": "/icon192.png", "sizes": "192x192", "type": "image/png"},
            {"src": "/icon512.png", "sizes": "512x512", "type": "image/png"}
        ]
    }
    return JSONResponse(m)

@app.get("/sw.js")
def sw():
    js = """
self.addEventListener('install', e => self.skipWaiting());
self.addEventListener('activate', e => self.clients.claim());
self.addEventListener('fetch', e => { e.respondWith(fetch(e.request)); });
"""
    return FileResponse(content=js, media_type="application/javascript")

  Helpers for SSE framing 
def sse(data: str) > str:
    return f"data: {data}\n\n"

  Exa client helper 
def make_exa_client():
    if not EXA_KEY:
        return None
    if HAS_EXA_SDK:
        try:
            return Exa(EXA_KEY)
        except Exception:
            return None
    return None

  OpenAI streaming via requests 
def gen_openai_stream(messages: List[Dict[str, Any]], mode: str) > Generator[str, None, None]:
    if not OPENAI_KEY:
        yield sse(json.dumps({"error":"OPENAI API key hiányzik"}))
        return
    url = ""
    headers = {"Authorization": f"Bearer {OPENAI_KEY}", "ContentType":"application/json"}
    payload = {
        "model": OPENAI_MODEL,
        "messages": messages,
        "temperature": 0.0 if mode=="fast" else 0.2,
        "max_tokens": 2000,
        "stream": True
    }
    try:
        with requests.post(url, headers=headers, json=payload, stream=True, timeout=300) as r:
            if r.status_code != 200:
                yield sse(json.dumps({"error": f"OpenAI hiba {r.status_code}", "details": r.text[:500]}))
                return
            for raw in r.iter_lines(decode_unicode=True):
                if not raw:
                    continue
                line = raw.strip()
                if line.startswith("data: "):
                    line = line[len("data: "):]
                if line == "[DONE]":
                    yield sse("[DONE]")
                    break
                try:
                    j = json.loads(line)
                except Exception:
                    continue
                for ch in j.get("choices", []):
                    delta = ch.get("delta", {})
                    content = delta.get("content")
                    if content:
                        yield sse(content)
    except Exception as e:
        yield sse(json.dumps({"error":"OpenAI stream hiba","details":str(e)}))

  Cerebras streaming (SDK preferred, else HTTP fallback) 
def gen_cerebras_stream(messages: List[Dict[str, Any]], mode: str) > Generator[str, None, None]:
     Try SDK
    if HAS_CEREBRAS and CEREBRAS_KEY:
        try:
            client = Cerebras(api_key=CEREBRAS_KEY)
            stream = client.chat.completions.create(
                messages=messages,
                model=CEREBRAS_MODEL,
                stream=True,
                max_completion_tokens=CEREBRAS_MAX_TOKENS,
                temperature=0.06 if mode=="fast" else 0.1,
                top_p=0.11,
                reasoning_effort="low"
            )
            for chunk in stream:
                try:
                    txt = chunk.choices[0].delta.content or ""
                except Exception:
                    txt = getattr(chunk, "text", "") or str(chunk)
                if txt:
                    yield sse(txt)
            yield sse("[DONE]")
            return
        except Exception as e:
            yield sse(json.dumps({"error":"Cerebras SDK hiba","details":str(e)}))
             fallthrough to HTTP

     fallback http
    if not CEREBRAS_URL or not CEREBRAS_KEY:
        yield sse(json.dumps({"error":"Cerebras nincs elérhető SDK és CEREBRAS_API_URL nincs beállítva"}))
        return
    headers = {"Authorization": f"Bearer {CEREBRAS_KEY}", "ContentType":"application/json"}
    payload = {
        "model": CEREBRAS_MODEL,
        "messages": messages,
        "temperature": 0.06 if mode=="fast" else 0.1,
        "max_tokens": CEREBRAS_MAX_TOKENS,
        "stream": True
    }
    try:
        with requests.post(CEREBRAS_URL, headers=headers, json=payload, stream=True, timeout=300) as r:
            if r.status_code != 200:
                yield sse(json.dumps({"error":f"Cerebras HTTP hiba {r.status_code}", "details": r.text[:400]}))
                return
            for raw in r.iter_lines(decode_unicode=True):
                if not raw:
                    continue
                line = raw.strip()
                if line.startswith("data: "):
                    line = line[len("data: "):]
                if line == "[DONE]":
                    yield sse("[DONE]")
                    break
                 attempt parse
                try:
                    j = json.loads(line)
                    if isinstance(j, dict) and "choices" in j:
                        for ch in j["choices"]:
                            delta = ch.get("delta", {})
                            c = delta.get("content")
                            if c:
                                yield sse(c)
                    else:
                         fallback text
                        txt = j.get("text") if isinstance(j, dict) else str(j)
                        if txt:
                            yield sse(txt)
                except Exception:
                    yield sse(line)
            yield sse("[DONE]")
    except Exception as e:
        yield sse(json.dumps({"error":"Cerebras HTTP stream hiba","details":str(e)}))

